#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# scripts/feature-flag-seed.sh — platform.feature_flags 權威旗標種子 / 同步工具
# Generated by gencode[platform-feature-flag-seed].
#
# 機制（provider-dynamic，依 archConfig.feature_flag_provider 切換）：
#   feature_flag_provider = ""（none，本專案 pin）→ 內建 DB 旗標引擎：
#     把 SCHEMA §Seed Data / EDD §20 權威定義的預設旗標 upsert 進 platform.feature_flags。
#   其它供應商（unleash / launchdarkly / flagsmith）→ 本後端未配置（classpath 無對應 SDK），
#     明確中止並提示；不硬編任何供應商、不內嵌任何 token（模板 Review #6/#7）。
#
# 旗標權威來源（單一 SSOT，與 migrations/V013__seed_feature_flags.sql 同一組）：
#   SCHEMA §Seed Data 定義的預設旗標＝1 個：deposit.real_payment_phase_b（FALSE / 0%）。
#   EDD §20.2 命名表為命名慣例示例（非具預設值之目錄）→ 不種子（Iron Law §1 / Anti-Fake）。
#
# 冪等（模板 Review #5 / EDD §20.7）：ON CONFLICT (flag_key) DO NOTHING —
#   只補缺漏旗標，絕不覆蓋營運方執行期已調整的 is_enabled / rollout_pct（kill-switch / canary）。
#
# 連線設定（模板 Review #7：憑證一律來自環境變數，腳本不含任何真實 token）：
#   DB_HOST（預設 yocat-pg.yocat.svc.cluster.local）/ DB_PORT（5432）/ DB_NAME（yocat_office）
#   / DB_USER（yocat）/ DB_PASSWORD（空）— 與 apps/api application.yml datasource 對齊。
#
# 用法：
#   bash scripts/feature-flag-seed.sh            # 內建 DB：seed/sync 權威旗標 + 驗證
#   DB_HOST=127.0.0.1 DB_PASSWORD=*** bash scripts/feature-flag-seed.sh
# ════════════════════════════════════════════════════════════════════════════
set -euo pipefail

# ── provider 切換（無 hardcoded provider；由環境 / archConfig 決定）────────────────
PROVIDER="${FEATURE_FLAG_PROVIDER:-}"   # "" (none/builtin) is this project's archConfig pin
case "$PROVIDER" in
  ""|none|builtin|db)
    : ;; # 內建 DB 旗標引擎 → 續行
  unleash|launchdarkly|flagsmith)
    echo "[feature-flag-seed] ERROR: provider='$PROVIDER' 未在本後端配置 (classpath 無對應 SDK；" >&2
    echo "  archConfig.feature_flag_provider 為空＝內建 DB)。若要改用外部供應商，" >&2
    echo "  需先在 ARCH/archConfig 選型並接入其 SDK，再於此擴充對應 seed 分支。" >&2
    exit 2 ;;
  *)
    echo "[feature-flag-seed] ERROR: 未知 provider='$PROVIDER'" >&2
    exit 2 ;;
esac

# ── 連線參數（libpq 環境變數；密碼僅來自環境）────────────────────────────────────
export PGHOST="${DB_HOST:-yocat-pg.yocat.svc.cluster.local}"
export PGPORT="${DB_PORT:-5432}"
export PGDATABASE="${DB_NAME:-yocat_office}"
export PGUSER="${DB_USER:-yocat}"
export PGPASSWORD="${DB_PASSWORD:-}"

command -v psql >/dev/null 2>&1 || { echo "[feature-flag-seed] ERROR: psql 不在 PATH" >&2; exit 3; }

echo "[feature-flag-seed] provider=builtin-db host=$PGHOST db=$PGDATABASE — seeding platform.feature_flags"

# ── 權威旗標 upsert（冪等；不覆蓋營運已調整值）──────────────────────────────────
#   新增旗標時：在此 VALUES 與 V013__seed_feature_flags.sql 同步追加（單一 SSOT）。
psql -v ON_ERROR_STOP=1 <<'SQL'
INSERT INTO platform.feature_flags (flag_key, is_enabled, rollout_pct, description) VALUES
  ('deposit.real_payment_phase_b', FALSE, 0, 'Phase B 真金流（預留，預設關閉）')
ON CONFLICT (flag_key) DO NOTHING;
SQL

# ── 驗證：每個權威旗標都必須存在（缺任一 → 非 0 退出，不得謊報 exit 0）──────────────
EXPECTED_FLAGS=("deposit.real_payment_phase_b")
MISSING=0
for flag in "${EXPECTED_FLAGS[@]}"; do
  present="$(psql -tAq -v ON_ERROR_STOP=1 \
    -c "SELECT 1 FROM platform.feature_flags WHERE flag_key = '${flag}';")"
  if [[ "$present" == "1" ]]; then
    echo "  ✅ $flag present"
  else
    echo "  ❌ $flag MISSING after seed" >&2
    MISSING=$((MISSING + 1))
  fi
done

if [[ "$MISSING" -gt 0 ]]; then
  echo "[feature-flag-seed] FAIL: $MISSING flag(s) missing after seed" >&2
  exit 1
fi

echo "[feature-flag-seed] OK: ${#EXPECTED_FLAGS[@]} authoritative flag(s) seeded/verified (idempotent)"
